arguments.content:
:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1E222D;
  --bg-tertiary: #2A2E39;
  --text-primary: #D1D4DC;
  --text-secondary: #787B86;
  --accent-blue: #2962FF;
  --accent-blue-hover: #1E53E5;
  --up-color: #089981;
  --down-color: #F7525F;
  --border-color: #2A2E39;
  --font-family: 'Inter', 'DM Sans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  font-size: 14px;
}

a {
  color: inherit;
  text-decoration: none;
}

a:hover {
  color: var(--accent-blue);
}

ul {
  list-style: none;
}

header {
  background-color: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 0 20px;
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  font-size: 20px;
  font-weight: 700;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-links {
  display: flex;
  gap: 20px;
}

.nav-links a {
  font-weight: 500;
  color: var(--text-primary);
  transition: color 0.2s;
}

.nav-links a:hover, .nav-links a.active {
  color: var(--accent-blue);
}

.btn {
  background-color: var(--accent-blue);
  color: #fff;
  border: none;
  border-radius: 4px;
  padding: 8px 16px;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.btn:hover {
  background-color: var(--accent-blue-hover);
}

.btn-outline {
  background-color: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-primary);
}

.btn-outline:hover {
  border-color: var(--text-secondary);
  background-color: transparent;
  color: #fff;
}

.up { color: var(--up-color); }
.down { color: var(--down-color); }

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
}

/* Tab systems */
.tabs {
  display: flex;
  gap: 16px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 20px;
  overflow-x: auto;
}

.tab {
  padding: 8px 0;
  cursor: pointer;
  font-weight: 500;
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
}

.tab:hover {
  color: var(--text-primary);
}

.tab.active {
  color: var(--accent-blue);
  border-bottom-color: var(--accent-blue);
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
}

/* Cards */
.card {
  background-color: var(--bg-secondary);
  border-radius: 8px;
  padding: 20px;
  border: 1px solid var(--border-color);
}

/* Tables */
.table-responsive {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th, td {
  padding: 12px;
  text-align: left;
  border-bottom: 1px solid var(--border-color);
}

th {
  color: var(--text-secondary);
  font-weight: 500;
  font-size: 12px;
  text-transform: uppercase;
}

tr:hover td {
  background-color: var(--bg-tertiary);
}

/* Grid Layouts */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }

/* Utilities */
.text-right { text-align: right; }
.text-center { text-align: center; }
.flex { display: flex; }
.flex-between { justify-content: space-between; }
.flex-col { flex-direction: column; }
.gap-2 { gap: 8px; }
.gap-4 { gap: 16px; }
.items-center { align-items: center; }
.mt-4 { margin-top: 16px; }
.mb-4 { margin-bottom: 16px; }
.mt-8 { margin-top: 32px; }
.mb-8 { margin-bottom: 32px; }

/* Mini Sparkline */
.sparkline {
  height: 20px;
  width: 60px;
  background-color: var(--bg-tertiary);
  border-radius: 2px;
  display: inline-block;
}
.sparkline.up-line { border-bottom: 2px solid var(--up-color); }
.sparkline.down-line { border-bottom: 2px solid var(--down-color); }

/* Badges */
.badge {
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
  background-color: var(--bg-tertiary);
}
.badge.gold { background-color: #f5b041; color: #111; }
.badge.platinum { background-color: #e5e7e9; color: #111; }

/* Footer */
footer {
  background-color: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 40px 20px;
  margin-top: 60px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 30px;
  max-width: 1200px;
  margin: 0 auto;
}
.footer-col h4 {
  color: #fff;
  margin-bottom: 16px;
  font-size: 14px;
}
.footer-col ul li {
  margin-bottom: 8px;
}
.footer-col a {
  color: var(--text-secondary);
  font-size: 13px;
}
.footer-col a:hover {
  color: #fff;
}

document.addEventListener('DOMContentLoaded', () => {
  // Generic Tab functionality
  const tabContainers = document.querySelectorAll('.tabs');

  tabContainers.forEach(container => {
    container.addEventListener('click', (e) => {
      if (e.target.classList.contains('tab')) {
        const targetId = e.target.getAttribute('data-target');
        const containerGroup = e.target.getAttribute('data-group');

        // Remove active class from all tabs in this container
        const tabs = container.querySelectorAll('.tab');
        tabs.forEach(tab => tab.classList.remove('active'));

        // Add active class to clicked tab
        e.target.classList.add('active');

        // Hide all content in this group
        if (containerGroup) {
          const contents = document.querySelectorAll(`.tab-content[data-group="${containerGroup}"]`);
          contents.forEach(content => content.classList.remove('active'));

          // Show target content
          const targetContent = document.getElementById(targetId);
          if (targetContent) {
            targetContent.classList.add('active');
          }
        }
      }
    });
  });

  // Watchlist Accordion toggle
  const accordionHeaders = document.querySelectorAll('.accordion-header');
  accordionHeaders.forEach(header => {
    header.addEventListener('click', () => {
      const content = header.nextElementSibling;
      const icon = header.querySelector('.toggle-icon');
      if (content.style.display === 'none') {
        content.style.display = 'block';
        if (icon) icon.textContent = '▼';
      } else {
        content.style.display = 'none';
        if (icon) icon.textContent = '▶';
      }
    });
  });

  // Generic Button Toggle (like video toggle)
  const toggleButtons = document.querySelectorAll('.btn-toggle');
  toggleButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      btn.classList.toggle('active');
      if (btn.classList.contains('active')) {
        btn.style.backgroundColor = 'var(--accent-blue)';
        btn.style.borderColor = 'var(--accent-blue)';
        btn.style.color = '#fff';
      } else {
        btn.style.backgroundColor = 'transparent';
        btn.style.borderColor = 'var(--border-color)';
        btn.style.color = 'var(--text-primary)';
      }
    });
  });
});
